<section class="panel table-wrap"><table class="table"><thead><tr><th>Khách hàng</th><th>Email</th><th>Điện thoại</th><th>Ngày tạo</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?= e($u['name']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['phone']) ?></td><td><?= e($u['created_at']) ?></td><td><span class="status <?= $u['is_active']?'completed':'cancelled' ?>"><?= $u['is_active']?'Hoạt động':'Đã khóa' ?></span></td><td><?php if(App\Core\Auth::can('customers.manage')):?><form action="/admin/customers/<?= $u['id'] ?>/toggle" method="post"><?= App\Core\Csrf::field() ?><button class="btn btn-light btn-sm" type="submit"><?= $u['is_active']?'Khóa':'Mở khóa' ?></button></form><?php endif?></td></tr><?php endforeach?></tbody></table></section>
